import { LucideIcon } from 'lucide-react';
import { useRouter } from 'next/router';
import { memo, useCallback } from 'react';
import { cn } from '@/utils/cn';

interface QuickActionCardProps {
  title: string;
  description: string;
  icon: LucideIcon;
  color: string;
  route?: string;
  onClick?: () => void;
  className?: string;
  style?: React.CSSProperties;
