  await db.query(
    `
    UPDATE infrastructure_incidents SET
      resolved = true,
      resolved_at = $2,
      time_to_resolve_seconds = $3
    WHERE id = $1
  `,
    [incidentId, resolvedAt, durationSeconds]
  );

  log.info(`[IncidentLearning] Tracked resolution time: ${durationSeconds}s for incident ${incidentId}`);
}

