/**
 * GET /api/analytics/reports/project-revenue
 *
 * Returns Fibertime revenue with per-project breakdown (T1 + children).
 * Source: "FT_Revenue" worksheet only — Data tab not used.
 *
 * Access restricted to authorised users via RBAC (analytics.reports / view)
 * or direct user-ID allowlist.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:cost-centre-revenue');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

// 🟢 WORKING: Cost Centre Revenue response types — Fibertime T1 with project children
export interface ProjectRevenueChild {
  project: string;
  revenue: number;
}

export interface CostCentreRevenueItem {
  tier1: string;
  revenue: number;
  children: ProjectRevenueChild[];
}

interface ApiResponse {
  success: true;
  data: CostCentreRevenueItem[];
  meta: { generatedAt: string; itemCount: number; sources: string[] };
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') return parseFloat(cell) || 0;
  return 0;
}

function findColExact(headers: unknown[], term: string): number {
  const lower = term.toLowerCase();
  return headers.findIndex((h) => String(h ?? '').toLowerCase().trim() === lower);
}

function findColContains(headers: unknown[], include: string): number {
  const incL = include.toLowerCase();
  return headers.findIndex((h) => String(h ?? '').toLowerCase().includes(incL));
}

/**
 * Parse "FT_Revenue" worksheet.
 * Groups rows by project, sums Debit Excl VAT per project.
 * Returns a single CostCentreRevenueItem with children sorted by revenue desc.
 */
function parseFibertimeSheet(values: unknown[][]): CostCentreRevenueItem {
  // Always returns something — never throws. Logs headers for diagnostics.
  const headers = (values[0] ?? []) as unknown[];

  logger.info('FT_Revenue headers', { headers: headers.slice(0, 20) });

  // "Debit Excl VAT" — try multiple patterns before giving up
  let debitCol = findColExact(headers, 'debit excl vat');
  if (debitCol < 0) debitCol = findColContains(headers, 'debit excl');
  if (debitCol < 0) debitCol = findColContains(headers, 'debit');
  if (debitCol < 0) debitCol = findColContains(headers, 'amount');
  if (debitCol < 0) debitCol = findColContains(headers, 'revenue');
  // Hard fallback: last numeric-looking column in first data row
  if (debitCol < 0 && values.length > 1) {
    const firstRow = values[1] as unknown[];
    for (let c = firstRow.length - 1; c >= 0; c--) {
      if (typeof firstRow[c] === 'number') { debitCol = c; break; }
    }
  }

  // Project column — "project" in header, fallback col 0
  let projectCol = findColContains(headers, 'project');
  if (projectCol < 0) projectCol = 0;

  logger.info('FT_Revenue column detection', { debitCol, projectCol });

  // If debitCol still not found, return Fibertime with revenue=0 and no children
  if (debitCol < 0) {
    logger.warn('FT_Revenue: could not detect revenue column');
    return { tier1: 'Fibertime', revenue: 0, children: [] };
  }

  const grouped = new Map<string, number>();

  for (let i = 1; i < values.length; i++) {
    const row = values[i] as unknown[];
    const project = String(row[projectCol] ?? '').trim();
    const amount = toNumber(row[debitCol]);
    if (!project && amount === 0) continue;
    // Use "(Unassigned)" if project name is empty but there's a value
    const key = project || '(Unassigned)';
    grouped.set(key, (grouped.get(key) ?? 0) + amount);
  }

  const children: ProjectRevenueChild[] = Array.from(grouped.entries())
    .map(([project, revenue]) => ({ project, revenue }))
    .sort((a, b) => b.revenue - a.revenue);

  const total = children.reduce((s, c) => s + c.revenue, 0);

  logger.info('FT_Revenue parsed', { projects: children.length, total });

  return { tier1: 'Fibertime', revenue: total, children };
}

// 🟢 WORKING: Cost Centre Revenue GET handler — reads live SharePoint FT_Revenue tab
export async function GET(_req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      {
        success: false,
        error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' },
      },
      { status: 403 }
    );
  }

  logger.info('Cost centre revenue requested', { userId });

  try {
    // Try both tab name variants (with and without space)
    let sheetValues: unknown[][] | null = null;
    try {
      const res = await getWorksheetRange('FT_Revenue');
      sheetValues = res.values ?? null;
    } catch {
      logger.warn('FT_Revenue (no space) failed — trying "FT_Revenue"');
    }
    if (!sheetValues || sheetValues.length < 2) {
      const res2 = await getWorksheetRange('FT_Revenue');
      sheetValues = res2.values ?? null;
    }
    if (!sheetValues || sheetValues.length < 2) {
      throw new Error('FT_Revenue sheet not found under either tab name variant');
    }

    const ft = parseFibertimeSheet(sheetValues);

    const response: ApiResponse = {
      success: true,
      data: [ft],
      meta: {
        generatedAt: new Date().toISOString(),
        itemCount: 1,
        sources: ['FT_Revenue'],
      },
    };

    return NextResponse.json(response);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Cost centre revenue fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

/**
 * useProjectRevenueData — React Query hook for the Cost Centre Revenue report.
 * Fetches Fibertime revenue with per-project breakdown from the Shareholder Model via the API.
 */

import { useQuery } from '@tanstack/react-query';

// 🟢 WORKING: Cost Centre Revenue types — Fibertime T1 with project children
export interface ProjectRevenueChild {
  project: string;
  revenue: number;
}

export interface CostCentreRevenueItem {
  tier1: string;
  revenue: number;
  children: ProjectRevenueChild[];
}

export interface CostCentreRevenueResponse {
  success: boolean;
  data: CostCentreRevenueItem[];
  meta: {
    generatedAt: string;
    itemCount: number;
    sources: string[];
  };
}

interface ApiErrorBody {
  error?: {
    message?: string;
  };
}

async function fetchCostCentreRevenue(): Promise<CostCentreRevenueResponse> {
  const res = await fetch('/api/analytics/reports/project-revenue');
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    throw new Error(body.error?.message ?? 'Failed to load cost centre revenue data');
  }
  return res.json() as Promise<CostCentreRevenueResponse>;
}

// 🟢 WORKING: React Query hook with 5-minute cache
export function useProjectRevenueData() {
  return useQuery<CostCentreRevenueResponse, Error>({
    queryKey: ['analytics', 'cost-centre-revenue'],
    queryFn: fetchCostCentreRevenue,
    staleTime: 5 * 60 * 1000,
  });
}

/**
 * CostCentreRevenueTable — Fibertime T1 row with expand/collapse project children.
 * T1 row is collapsible; child rows show per-project revenue.
 */
'use client';

import { useState } from 'react';
import { ChevronRight, ChevronDown } from 'lucide-react';
import type { CostCentreRevenueItem } from '../project-revenue/useProjectRevenueData';

function fZAR(v: number) {
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `R\u00a0${s}`;
}

interface Props {
  rows: CostCentreRevenueItem[];
}

// 🟢 WORKING: Fibertime expand/collapse table with per-project revenue breakdown
export function CostCentreRevenueTable({ rows }: Props) {
  const [expandedRows, setExpandedRows] = useState<Set<string>>(
    () => new Set(rows.length > 0 ? [rows[0].tier1] : [])
  );

  function toggleRow(tier1: string) {
    setExpandedRows((prev) => {
      const next = new Set(prev);
      if (next.has(tier1)) {
        next.delete(tier1);
      } else {
        next.add(tier1);
      }
      return next;
    });
  }

  const grandTotal = rows.reduce((s, r) => s + r.revenue, 0);

  const th =
    'px-4 py-2.5 text-left text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';
  const thR = `${th} text-right`;

  return (
    <div className="overflow-x-auto rounded-lg border border-gray-700">
      <table className="w-full text-sm border-collapse">
        <thead>
          <tr style={{ backgroundColor: '#1a3a4a' }}>
            <th className={th} style={{ minWidth: 260 }}>
              Cost Centre T1
            </th>
            <th className={thR} style={{ minWidth: 160 }}>
              Revenue (R)
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const isExpanded = expandedRows.has(row.tier1);
            return (
              <>
                {/* T1 header row — clickable */}
                <tr
                  key={`t1-${row.tier1}`}
                  onClick={() => toggleRow(row.tier1)}
                  className="cursor-pointer select-none"
                  style={{ backgroundColor: '#1a3a4a' }}
                >
                  <td className="px-4 py-2.5 text-white font-bold">
                    <span className="inline-flex items-center gap-2">
                      {isExpanded ? (
                        <ChevronDown className="w-4 h-4 flex-shrink-0 text-blue-400" />
                      ) : (
                        <ChevronRight className="w-4 h-4 flex-shrink-0 text-blue-400" />
                      )}
                      {row.tier1}
                    </span>
                  </td>
                  <td className="px-4 py-2.5 text-right tabular-nums text-white font-bold">
                    {fZAR(row.revenue)}
                  </td>
                </tr>

                {/* Child project rows */}
                {isExpanded &&
                  row.children.map((child, ci) => (
                    <tr
                      key={`child-${row.tier1}-${child.project}`}
                      className={ci % 2 === 0 ? 'bg-gray-900' : 'bg-gray-800/60'}
                    >
                      <td className="px-4 py-2 pl-8 text-gray-200 border-l-2 border-blue-500/40">
                        {child.project}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums text-gray-300">
                        {fZAR(child.revenue)}
                      </td>
                    </tr>
                  ))}
              </>
            );
          })}
        </tbody>
        <tfoot>
          <tr className="border-t-2 border-gray-500" style={{ backgroundColor: '#1a3a4a' }}>
            <td className="px-4 py-2.5 text-white font-bold">Grand Total</td>
            <td className="px-4 py-2.5 text-right tabular-nums text-white font-bold">
              {fZAR(grandTotal)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

/**
 * Analytics Reports Registry
 * Central registry of all available analytics reports.
 * Add new report definitions here and map their components in the client page.
 */

/** Report category types */
export type ReportCategory = 'financial' | 'operational' | 'procurement';

/** Metadata definition for a single analytics report */
export interface ReportDefinition {
  /** Unique report identifier — used as key in REPORT_COMPONENTS map */
  id: string;
  /** Human-readable report name */
  name: string;
  /** Short description shown on the report card */
  description: string;
  /** Logical grouping category */
  category: ReportCategory;
}

// 🟢 WORKING: Registry of all available analytics reports
export const REPORT_REGISTRY: ReportDefinition[] = [
  {
    id: 'revenue-overview',
    name: 'Cashflow Overview',
    description: 'Monthly Cash In, Cash Out and Net from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'project-revenue',
    name: 'Cost Centre Revenue',
    description: 'Contract revenue grouped by Cost Centre T1 and Cost Centre from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'expense-pivot',
    name: 'Expense Pivot',
    description: 'Monthly expense breakdown by category — mirrors Excel pivot',
    category: 'financial',
  },
  {
    id: 'project-fin',
    name: 'Project COS/Rev \u2014 Forecast',
    description: 'Project-level cost, revenue and net by month from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'project-detail',
    name: 'Project Detail',
    description: 'Per-project COS breakdown and financial summary with project slicer',
    category: 'financial',
  },
];

/**
 * ProjectRevenue — Cost Centre Revenue report.
 * Table tab: T1-only data grid (Cost Centre T1 | Revenue)
 * Charts tab: placeholder — awaiting spec from Lew
 */

'use client';

import { useProjectRevenueData } from './useProjectRevenueData';
import { AlertCircle, Loader2 } from 'lucide-react';
import { ReportTabLayout } from '../ReportTabLayout';
import { CostCentreRevenueTable } from '../tables/ProjectRevenueTable';

// 🟢 WORKING: Cost Centre Revenue — tiered table view
export default function ProjectRevenue() {
  const { data, isLoading, error } = useProjectRevenueData();

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64 text-gray-400">
        <Loader2 className="w-6 h-6 animate-spin mr-2" />
        Loading cost centre data&hellip;
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center gap-2 text-red-400 p-4">
        <AlertCircle className="w-5 h-5 flex-shrink-0" />
        <span>{error.message}</span>
      </div>
    );
  }

  const rows = data?.data ?? [];

  return (
    <ReportTabLayout
      tableContent={<CostCentreRevenueTable rows={rows} />}
      chartsContent={
        <div className="flex items-center justify-center h-48 text-gray-500 text-sm italic">
          Charts coming soon — awaiting spec
        </div>
      }
    />
  );
}

