/**
 * useRevenueData — React Query hook for the Revenue Overview (cashflow) report.
 * Fetches monthly Cash In / Cash Out / Net data from SharePoint via the API.
 */

import { useQuery } from '@tanstack/react-query';

/** A single monthly cashflow data point */
export interface CashflowDataPoint {
  /** Month label, e.g. "Jan 2026" */
  label: string;
  /** Cash inflows for the month */
  cashIn: number;
  /** Cash outflows for the month */
  cashOut: number;
  /** Net cash movement (Cash In − Cash Out) */
  net: number;
}

/** Response shape returned by /api/analytics/reports/revenue-overview */
export interface CashflowResponse {
  success: boolean;
  data: CashflowDataPoint[];
  meta: {
    /** Optional informational note */
    note?: string;
    /** ISO timestamp of when this data was generated */
    generatedAt: string;
    /** Number of months returned */
    monthCount: number;
    /** Currency code, always "ZAR" */
    currency: string;
  };
}

/** Error response shape from the API */
interface ApiErrorBody {
  error?: {
    message?: string;
  };
}

async function fetchRevenueData(): Promise<CashflowResponse> {
  const res = await fetch('/api/analytics/reports/revenue-overview');
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    throw new Error(body.error?.message ?? 'Failed to load revenue data');
  }
  return res.json() as Promise<CashflowResponse>;
}

// 🟢 WORKING: React Query hook with 5-minute cache
export function useRevenueData() {
  return useQuery<CashflowResponse, Error>({
    queryKey: ['analytics', 'revenue-overview'],
    queryFn: fetchRevenueData,
    staleTime: 5 * 60 * 1000,
  });
}

/**
 * GET /api/analytics/reports/project-revenue
 *
 * Returns Cost Centre Profitability: COS vs Revenue per project.
 * Sources: "FT_Revenue" (actual invoiced revenue) + "Project_Costing" (COS Total).
 *
 * Access restricted to authorised users via RBAC (analytics.reports / view)
 * or direct user-ID allowlist.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:cost-centre-profitability');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

// 🟢 WORKING: Cost Centre Profitability response types — COS vs Revenue per project
export interface ProjectProfitabilityRow {
  project: string;
  revenue: number;
  cos: number;
  grossProfit: number;
  margin: number;
}

export interface CostCentreRevenueItem {
  tier1: string;
  revenue: number;
  cos: number;
  grossProfit: number;
  margin: number;
  children: ProjectProfitabilityRow[];
}

interface ApiResponse {
  success: true;
  data: CostCentreRevenueItem[];
  meta: { generatedAt: string; itemCount: number; sources: string[] };
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') return parseFloat(cell.replace(/[^0-9.\-]/g, '')) || 0;
  return 0;
}

function findColContains(headers: unknown[], include: string): number {
  const incL = include.toLowerCase();
  return headers.findIndex((h) => String(h ?? '').toLowerCase().includes(incL));
}

/**
 * Parse "FT_Revenue" worksheet.
 * Header row at index 0.
 * col 6 = "Project Name", col 9 = " Debit Excl VAT" (detect by "debit excl").
 * Returns Map<projectName, totalRevenue>.
 */
function parseFTRevenue(values: unknown[][]): Map<string, number> {
  const headers = (values[0] ?? []) as unknown[];
  logger.info('FT_Revenue headers', { headers: headers.slice(0, 15) });

  // Project Name — col 6 expected, fallback search
  let projectCol = 6;
  const projectHeader = String(headers[6] ?? '').toLowerCase();
  if (!projectHeader.includes('project')) {
    projectCol = findColContains(headers, 'project name');
    if (projectCol < 0) projectCol = findColContains(headers, 'project');
    if (projectCol < 0) projectCol = 6;
  }

  // Debit Excl VAT — detect by "debit excl", fallback col 9
  let debitCol = findColContains(headers, 'debit excl');
  if (debitCol < 0) debitCol = 9;

  logger.info('FT_Revenue column detection', { projectCol, debitCol });

  const grouped = new Map<string, number>();

  for (let i = 1; i < values.length; i++) {
    const row = values[i] as unknown[];
    const project = String(row[projectCol] ?? '').trim();
    const amount = toNumber(row[debitCol]);
    if (!project && amount === 0) continue;
    const key = project || '(Unassigned)';
    grouped.set(key, (grouped.get(key) ?? 0) + amount);
  }

  logger.info('FT_Revenue parsed', { projects: grouped.size });
  return grouped;
}

/**
 * Parse "Project_Costing" worksheet.
 * Header row at index 2 (rows 0+1 are meta/section headers).
 * col 3 = project name, col 9 = "COS - Total".
 * Data rows start at index 3, stop when col 3 is empty.
 * Returns Map<projectName, cosTotal>.
 */
function parseProjectCosting(values: unknown[][]): Map<string, number> {
  if (values.length < 4) {
    logger.warn('Project_Costing: insufficient rows', { rowCount: values.length });
    return new Map();
  }

  const headers = (values[2] ?? []) as unknown[];
  logger.info('Project_Costing headers (row 2)', { headers: headers.slice(0, 15) });

  const cosMap = new Map<string, number>();

  for (let i = 3; i < values.length; i++) {
    const row = values[i] as unknown[];
    const project = String(row[3] ?? '').trim();
    if (!project) break; // stop at first empty project name
    const cos = toNumber(row[9]);
    cosMap.set(project, cos);
  }

  logger.info('Project_Costing parsed', { projects: cosMap.size });
  return cosMap;
}

/**
 * Merge FT_Revenue + Project_Costing into a single CostCentreRevenueItem.
 */
function buildProfitabilityItem(
  revenueMap: Map<string, number>,
  cosMap: Map<string, number>
): CostCentreRevenueItem {
  const children: ProjectProfitabilityRow[] = Array.from(revenueMap.entries())
    .map(([project, revenue]) => {
      const cos = cosMap.get(project) ?? 0;
      const grossProfit = revenue - cos;
      const margin = revenue !== 0 ? grossProfit / revenue : 0;
      return { project, revenue, cos, grossProfit, margin };
    })
    .sort((a, b) => b.revenue - a.revenue);

  const totalRevenue = children.reduce((s, c) => s + c.revenue, 0);
  const totalCos = children.reduce((s, c) => s + c.cos, 0);
  const totalGP = totalRevenue - totalCos;
  const totalMargin = totalRevenue !== 0 ? totalGP / totalRevenue : 0;

  return {
    tier1: 'Fibertime',
    revenue: totalRevenue,
    cos: totalCos,
    grossProfit: totalGP,
    margin: totalMargin,
    children,
  };
}

// 🟢 WORKING: Cost Centre Profitability GET handler — FT_Revenue + Project_Costing
export async function GET(_req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      {
        success: false,
        error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' },
      },
      { status: 403 }
    );
  }

  logger.info('Cost centre profitability requested', { userId });

  try {
    // Fetch both sheets in parallel — Project_Costing failure is non-fatal
    const [ftResult, costingResult] = await Promise.allSettled([
      getWorksheetRange('FT_Revenue'),
      getWorksheetRange('Project_Costing'),
    ]);

    // FT_Revenue is required
    if (ftResult.status === 'rejected') {
      throw new Error(`FT_Revenue fetch failed: ${String(ftResult.reason)}`);
    }

    const ftValues = ftResult.value.values ?? [];
    if (ftValues.length < 2) {
      throw new Error('FT_Revenue sheet returned no data rows');
    }

    const revenueMap = parseFTRevenue(ftValues);

    // Project_Costing is optional — degrade gracefully to COS = 0
    let cosMap = new Map<string, number>();
    const sources = ['FT_Revenue'];

    if (costingResult.status === 'fulfilled') {
      const costingValues = costingResult.value.values ?? [];
      cosMap = parseProjectCosting(costingValues);
      sources.push('Project_Costing');
    } else {
      logger.warn('Project_Costing fetch failed — COS will be 0 for all projects', {
        error: String(costingResult.reason),
      });
    }

    const ft = buildProfitabilityItem(revenueMap, cosMap);

    const response: ApiResponse = {
      success: true,
      data: [ft],
      meta: {
        generatedAt: new Date().toISOString(),
        itemCount: 1,
        sources,
      },
    };

    return NextResponse.json(response);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Cost centre profitability fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

/**
 * GET /api/analytics/reports/expense-pivot
 *
 * Returns pivot data: Category T2 rows × month columns, Amount Excl. VAT sums.
 * Query params: ?type=Expense (default) | Income | All
 * Filter: only rows where Split (col 13) === "Included"
 *
 * Access restricted to authorised users via RBAC (analytics.reports / view)
 * or direct user-ID allowlist.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:expense-pivot');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

/** Valid filter type values */
type PivotType = 'Expense' | 'Income' | 'All';

/** Month names indexed 0-11 */
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Converts an Excel date serial (Date-M column) to "YYYY-MMM" key.
 * Excel epoch: serial 1 = 1900-01-01.
 */
function excelSerialToMonthKey(serial: number): string {
  const date = new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000);
  const year = date.getUTCFullYear();
  const mon = MONTH_NAMES[date.getUTCMonth()];
  return `${year}-${mon}`;
}

/**
 * Sorts month keys like "2025-Apr", "2026-Jan" chronologically.
 * Parses year and month index for comparison.
 */
function monthKeySortValue(key: string): number {
  const [yearStr, monStr] = key.split('-');
  const year = parseInt(yearStr, 10);
  const monIdx = MONTH_NAMES.indexOf(monStr);
  return year * 12 + monIdx;
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') return parseFloat(cell) || 0;
  return 0;
}

function toString(cell: unknown): string {
  if (typeof cell === 'string') return cell.trim();
  if (cell == null) return '';
  return String(cell).trim();
}

/** Row in the pivot output */
interface PivotRow {
  category: string;
  monthly: Record<string, number>;
  yearTotals: Record<string, number>;
  grandTotal: number;
}

/** Full pivot response data shape */
interface PivotData {
  months: string[];
  yearGroups: Record<string, string[]>;
  rows: PivotRow[];
  grandTotals: {
    monthly: Record<string, number>;
    yearTotals: Record<string, number>;
    grandTotal: number;
  };
}

// 🟢 WORKING: Expense pivot GET handler — reads live SharePoint Data worksheet
export async function GET(req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation: RBAC check + allowlist fallback ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      {
        success: false,
        error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' },
      },
      { status: 403 }
    );
  }

  // --- Parse query param ---
  const rawType = req.nextUrl.searchParams.get('type') ?? 'Expense';
  const typeFilter: PivotType =
    rawType === 'Income' ? 'Income' : rawType === 'All' ? 'All' : 'Expense';

  logger.info('Expense pivot requested', { userId, typeFilter });

  try {
    const { values } = await getWorksheetRange('Data');

    if (!values || values.length < 2) {
      throw new Error('Data sheet returned insufficient data');
    }

    // Accumulator: categoryT2 → monthKey → sum
    const accumulator = new Map<string, Map<string, number>>();
    const monthKeySet = new Set<string>();

    // Skip header row (index 0); iterate from index 1
    for (let i = 1; i < values.length; i++) {
      const row = values[i] as unknown[];

      // Skip if Split (col 13) !== "Included"
      if (toString(row[13]) !== 'Included') continue;

      // Apply type filter
      const rowType = toString(row[2]);
      if (typeFilter === 'Expense' && rowType !== 'Expense') continue;
      if (typeFilter === 'Income' && rowType !== 'Income') continue;
      // typeFilter === 'All' passes everything

      // Get Date-M serial (col 1)
      const dateMSerial = toNumber(row[1]);
      if (dateMSerial <= 0) continue;
      const monthKey = excelSerialToMonthKey(dateMSerial);

      // Get Category T2 (col 10)
      const categoryT2 = toString(row[10]) || '(Uncategorised)';

      // Get Amount Excl. VAT (col 5)
      const amount = toNumber(row[5]);

      // Accumulate
      monthKeySet.add(monthKey);
      if (!accumulator.has(categoryT2)) {
        accumulator.set(categoryT2, new Map());
      }
      const catMap = accumulator.get(categoryT2)!;
      catMap.set(monthKey, (catMap.get(monthKey) ?? 0) + amount);
    }

    // Sort months chronologically
    const months = Array.from(monthKeySet).sort(
      (a, b) => monthKeySortValue(a) - monthKeySortValue(b)
    );

    // Build yearGroups
    const yearGroupsMap = new Map<string, string[]>();
    for (const mk of months) {
      const year = mk.split('-')[0];
      if (!yearGroupsMap.has(year)) yearGroupsMap.set(year, []);
      yearGroupsMap.get(year)!.push(mk);
    }
    const yearGroups: Record<string, string[]> = Object.fromEntries(yearGroupsMap);
    const years = Array.from(yearGroupsMap.keys()).sort();

    // Build rows with full monthly fill-in
    const rows: PivotRow[] = [];
    for (const [category, catMap] of accumulator) {
      const monthly: Record<string, number> = {};
      const yearTotals: Record<string, number> = {};
      let grandTotal = 0;

      for (const mk of months) {
        const val = catMap.get(mk) ?? 0;
        monthly[mk] = val;
        const year = mk.split('-')[0];
        yearTotals[year] = (yearTotals[year] ?? 0) + val;
        grandTotal += val;
      }

      // Ensure all years have an entry even if zero
      for (const yr of years) {
        if (!(yr in yearTotals)) yearTotals[yr] = 0;
      }

      rows.push({ category, monthly, yearTotals, grandTotal });
    }

    // Sort by grandTotal descending
    rows.sort((a, b) => a.category.localeCompare(b.category));

    // Build grand totals row
    const gtMonthly: Record<string, number> = {};
    const gtYearTotals: Record<string, number> = {};
    let gtGrandTotal = 0;

    for (const mk of months) {
      gtMonthly[mk] = rows.reduce((sum, r) => sum + (r.monthly[mk] ?? 0), 0);
      const year = mk.split('-')[0];
      gtYearTotals[year] = (gtYearTotals[year] ?? 0) + gtMonthly[mk];
      gtGrandTotal += gtMonthly[mk];
    }
    for (const yr of years) {
      if (!(yr in gtYearTotals)) gtYearTotals[yr] = 0;
    }

    const data: PivotData = {
      months,
      yearGroups,
      rows,
      grandTotals: { monthly: gtMonthly, yearTotals: gtYearTotals, grandTotal: gtGrandTotal },
    };

    return NextResponse.json({ success: true, data });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Expense pivot fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

/**
 * GET /api/analytics/reports/project-fin
 *
 * Returns Project COS, Revenue, and Net data from the Shareholder Model
 * "Project_Fin" worksheet via SharePoint Graph API.
 *
 * Sheet structure:
 *   Row 1: Title row
 *   Row 2: "Project COS" section header with date serials in cols 3+
 *   Rows 3-N: Project COS data rows [name, scope, actual, ...monthly]
 *   Then: "Project Revenue" section header row
 *   Then: Project Revenue data rows
 *   Then: "Project Net" section header row
 *   Then: Project Net data rows
 *
 * Access restricted to authorised users via RBAC or direct allowlist.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:project-fin');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                     'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Converts an Excel date serial to "MMM-YY" label (e.g. 45717 → "Mar-25").
 * Excel epoch: serial 1 = 1900-01-01, adjusted for Lotus 1900 bug.
 */
function serialToMonthLabel(serial: number): string {
  const date = new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000);
  const mon = MONTH_NAMES[date.getUTCMonth()];
  const yr = String(date.getUTCFullYear()).slice(-2);
  return `${mon}-${yr}`;
}

/** Returns the numeric sort key for a "MMM-YY" label for chronological ordering. */
function monthLabelSortKey(label: string): number {
  const [mon, yrStr] = label.split('-');
  const year = parseInt(yrStr, 10) + (parseInt(yrStr, 10) < 50 ? 2000 : 1900);
  const monIdx = MONTH_NAMES.indexOf(mon);
  return year * 12 + monIdx;
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') {
    const parsed = parseFloat(cell.replace(/,/g, ''));
    return isNaN(parsed) ? 0 : parsed;
  }
  return 0;
}

function toString(cell: unknown): string {
  if (typeof cell === 'string') return cell.trim();
  if (cell == null) return '';
  return String(cell).trim();
}

/** Per-project financial data keyed by month label */
interface ProjectMonthlyData {
  actual: number;
  [monthLabel: string]: number;
}

/** Full section data: projectName → monthly values */
type SectionData = Record<string, ProjectMonthlyData>;

/** Totals row for a section */
interface SectionTotals {
  actual: number;
  [monthLabel: string]: number;
}

/** Complete response payload */
interface ProjectFinData {
  months: string[];
  projects: string[];
  cos: SectionData;
  revenue: SectionData;
  net: SectionData;
  totals: {
    cos: SectionTotals;
    revenue: SectionTotals;
    net: SectionTotals;
  };
}

/** Section keys we scan for in column 0 of the sheet */
const SECTION_HEADERS = ['Project COS', 'Project Revenue', 'Project Net'] as const;
type SectionKey = (typeof SECTION_HEADERS)[number];

/**
 * Parses a section of data rows from the sheet.
 * Starts at `startIndex` (first data row after the section header).
 * Stops when it hits another section header or end of rows.
 * Returns the project entries and the index of the next section header.
 */
function parseSection(
  rows: unknown[][],
  startIndex: number,
  monthSerials: number[],
  currentMonthSerial: number
): { entries: Map<string, ProjectMonthlyData>; nextSectionIndex: number } {
  const entries = new Map<string, ProjectMonthlyData>();
  let i = startIndex;

  while (i < rows.length) {
    const row = rows[i] as unknown[];
    const col0 = toString(row[0]);

    // Stop if we hit another section header
    if (SECTION_HEADERS.some(h => col0 === h)) break;

    // Skip blank or separator rows
    if (col0) {
      const projectName = col0;
      const actual = toNumber(row[2]);
      const monthly: ProjectMonthlyData = { actual };

      for (let c = 0; c < monthSerials.length; c++) {
        if (monthSerials[c] <= currentMonthSerial) {
          const label = serialToMonthLabel(monthSerials[c]);
          // cols 3+ correspond to month index c
          monthly[label] = toNumber(row[3 + c]);
        }
      }

      entries.set(projectName, monthly);
    }

    i++;
  }

  return { entries, nextSectionIndex: i };
}

/**
 * Computes totals across all projects for a section.
 */
function computeSectionTotals(
  entries: Map<string, ProjectMonthlyData>,
  months: string[]
): SectionTotals {
  const totals: SectionTotals = { actual: 0 };
  for (const mon of months) totals[mon] = 0;

  for (const data of entries.values()) {
    totals.actual += data.actual;
    for (const mon of months) {
      totals[mon] = (totals[mon] ?? 0) + (data[mon] ?? 0);
    }
  }

  return totals;
}

// 🟢 WORKING: Project Fin GET handler — reads live SharePoint Project_Fin worksheet
export async function GET(_req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      {
        success: false,
        error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' },
      },
      { status: 403 }
    );
  }

  logger.info('Project Fin report requested', { userId });

  try {
    const { values } = await getWorksheetRange('Project_Fin');

    if (!values || values.length < 3) {
      throw new Error('Project_Fin sheet returned insufficient data');
    }

    // Row 0 (index 0): title row — skip
    // Row 1 (index 1): first section header "Project COS" with date serials in cols 3+
    const headerRow = values[1] as unknown[];

    // Extract date serials from cols 3+ (stop at empty/non-numeric)
    const monthSerials: number[] = [];
    for (let c = 3; c < headerRow.length; c++) {
      const serial = toNumber(headerRow[c]);
      if (serial > 40000) {
        // Valid Excel date serial (reasonable range for 2010–2040)
        monthSerials.push(serial);
      }
    }

    if (monthSerials.length === 0) {
      throw new Error('No date serials found in Project_Fin header row');
    }

    // Determine current month serial — cut off future forecast columns
    const now = new Date();
    // End-of-current-month serial: first day of next month minus 1 day
    const currentMonthEndSerial =
      (new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 0)).getTime() -
        new Date(Date.UTC(1899, 11, 30)).getTime()) /
      86400000;

    // Build label list for months up to current (sorted)
    const validMonthSerials = monthSerials.filter(s => s <= currentMonthEndSerial);
    const months = validMonthSerials
      .map(s => serialToMonthLabel(s))
      // Deduplicate (two serials could map to the same label in edge cases)
      .filter((v, i, arr) => arr.indexOf(v) === i)
      .sort((a, b) => monthLabelSortKey(a) - monthLabelSortKey(b));

    // --- Parse 3 sections ---
    // Find section header rows by scanning col 0
    let cosStartIndex = -1;
    let revStartIndex = -1;
    let netStartIndex = -1;

    for (let i = 0; i < values.length; i++) {
      const row = values[i] as unknown[];
      const col0 = toString(row[0]);
      if (col0 === 'Project COS' && cosStartIndex === -1) cosStartIndex = i + 1;
      else if (col0 === 'Project Revenue' && revStartIndex === -1) revStartIndex = i + 1;
      else if (col0 === 'Project Net' && netStartIndex === -1) netStartIndex = i + 1;
    }

    if (cosStartIndex === -1 || revStartIndex === -1 || netStartIndex === -1) {
      throw new Error(
        'Could not locate one or more section headers in Project_Fin (COS/Revenue/Net)'
      );
    }

    const { entries: cosEntries } = parseSection(
      values as unknown[][],
      cosStartIndex,
      monthSerials,
      currentMonthEndSerial
    );
    const { entries: revEntries } = parseSection(
      values as unknown[][],
      revStartIndex,
      monthSerials,
      currentMonthEndSerial
    );
    const { entries: netEntries } = parseSection(
      values as unknown[][],
      netStartIndex,
      monthSerials,
      currentMonthEndSerial
    );

    // Collect unique project names (preserve order from COS section as primary)
    const projectSet = new Set<string>([
      ...cosEntries.keys(),
      ...revEntries.keys(),
      ...netEntries.keys(),
    ]);
    const projects = Array.from(projectSet);

    const cos: SectionData = Object.fromEntries(cosEntries);
    const revenue: SectionData = Object.fromEntries(revEntries);
    const net: SectionData = Object.fromEntries(netEntries);

    const data: ProjectFinData = {
      months,
      projects,
      cos,
      revenue,
      net,
      totals: {
        cos: computeSectionTotals(cosEntries, months),
        revenue: computeSectionTotals(revEntries, months),
        net: computeSectionTotals(netEntries, months),
      },
    };

    logger.info('Project Fin data parsed', {
      projects: projects.length,
      months: months.length,
    });

    return NextResponse.json({ success: true, data });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Project Fin fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

/**
 * GET /api/analytics/reports/project-detail
 *
 * Returns per-project COS sub-category breakdown and financial summary
 * sourced directly from the live Data tab and FT_Invoice tab.
 *
 * Data tab column map (row 0 = headers):
 *   Col 0:  Date serial (Excel)
 *   Col 2:  Type ("Income" / "Expense")
 *   Col 5:  Amount Excl. VAT
 *   Col 10: Category T2 (COS sub-category)
 *   Col 13: Split ("Included" or other)
 *   Col 15: Cost Centre T2 = project name ← slicer key
 *
 * FT_Invoice tab column map:
 *   Col 1:  Date_M serial (month grouping)
 *   Col 3:  Type filter — only "invoice" rows
 *   Col 6:  Project Name
 *   Col 9:  Debit (invoice amount)
 *
 * Query params:
 *   ?project=Mohadin  (defaults to "Mohadin")
 *
 * Access restricted to authorised users (Hein / Lew) or analytics.reports RBAC.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:project-detail');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

/**
 * Projects that appear in Cost Centre T2 of the Data tab.
 * Non-project entries (BICT-US, OPEX, etc.) are excluded.
 */
const KNOWN_PROJECTS = [
  'Etwatwa POP 2',
  'Grabouw',
  'Ivory Park',
  'Kuruman',
  'Lawley',
  'Malmesbury',
  'Mamelodi POP 1',
  'Mohadin',
  'Steenvilla',
  'TBC',
  'Tembisa 3',
  'Themb\'elihle',
  'Thembisa POP 1 (P1/2)',
  'Thembisa POP 2 (P1/2)',
  'Thembisa POP 3 (P1/2)',
  'Tonga',
].sort();

/** All 8 standard COS sub-categories — shown even when zero for selected project */
const COS_CATEGORIES = [
  'COS - Ad Hoc',
  'COS - Casuals',
  'COS - Fuel',
  'COS - Overheads',
  'COS - Sales',
  'COS - Stock',
  'COS - Sub-Contractor',
  'COS - Wayleaves',
];

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Converts an Excel date serial to "MMM-YY" label.
 * Excel epoch: serial 1 = 1900-01-01, with Lotus-1-2-3 leap-year bug
 * handled by the UTC(1899, 11, 30) base.
 */
function serialToMonthLabel(serial: number): string {
  const date = new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000);
  const mon = MONTH_NAMES[date.getUTCMonth()];
  const yr = String(date.getUTCFullYear()).slice(-2);
  return `${mon}-${yr}`;
}

/** Sort comparator value for "MMM-YY" month labels */
function monthLabelSortValue(label: string): number {
  const [monStr, yrStr] = label.split('-');
  const year = 2000 + parseInt(yrStr, 10);
  const monIdx = MONTH_NAMES.indexOf(monStr);
  return year * 12 + monIdx;
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') {
    const parsed = parseFloat(cell.replace(/,/g, ''));
    return isNaN(parsed) ? 0 : parsed;
  }
  return 0;
}

function toStr(cell: unknown): string {
  if (typeof cell === 'string') return cell.trim();
  if (cell == null) return '';
  return String(cell).trim();
}

/** Monthly values with a total field */
interface MonthlyValues {
  total: number;
  monthly: Record<string, number>;
}

/** Full response payload for the Project Detail report */
interface ProjectDetailData {
  project: string;
  availableProjects: string[];
  months: string[];
  cosActual: Record<string, MonthlyValues>;
  cosTotal: MonthlyValues;
  summary: {
    activations: MonthlyValues;
    revenue: MonthlyValues;
    gross: MonthlyValues;
    net: MonthlyValues;
  };
}

/** Initialises a MonthlyValues with zero for all known months */
function emptyMonthly(months: string[]): MonthlyValues {
  return {
    total: 0,
    monthly: Object.fromEntries(months.map(m => [m, 0])),
  };
}

/** Accumulates a value into a MonthlyValues record (mutates in place) */
function accumulate(target: MonthlyValues, month: string, amount: number): void {
  target.monthly[month] = (target.monthly[month] ?? 0) + amount;
  target.total += amount;
}

// 🟢 WORKING: Project Detail GET handler — reads live SharePoint Data + FT_Invoice tabs
export async function GET(req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation: RBAC check + allowlist fallback ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      { success: false, error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' } },
      { status: 403 }
    );
  }

  const projectName = req.nextUrl.searchParams.get('project') ?? 'Mohadin';

  if (!KNOWN_PROJECTS.includes(projectName)) {
    return NextResponse.json(
      { success: false, error: { code: 'NOT_FOUND', message: `Unknown project: ${projectName}` } },
      { status: 404 }
    );
  }

  logger.info('Project Detail report requested', { userId, projectName });

  try {
    // Fetch both worksheets in parallel
    const [{ values: dataRows }, { values: invoiceRows }] = await Promise.all([
      getWorksheetRange('Data'),
      getWorksheetRange('FT_Invoice'),
    ]);

    if (!dataRows || dataRows.length < 2) {
      throw new Error('Data sheet returned insufficient data');
    }

    // -----------------------------------------------------------------------
    // Pass 1: Determine the full month span from Data tab for this project
    // -----------------------------------------------------------------------
    const monthSet = new Set<string>();

    for (let i = 1; i < dataRows.length; i++) {
      const row = dataRows[i] as unknown[];
      if (toStr(row[15]) !== projectName) continue;
      if (toStr(row[13]) !== 'Included') continue;
      if (toStr(row[2]) !== 'Expense') continue;
      const cat = toStr(row[10]);
      if (!cat.startsWith('COS')) continue;

      const serial = toNumber(row[0]);
      if (serial > 0) monthSet.add(serialToMonthLabel(serial));
    }

    // Also collect months from FT_Invoice for this project
    if (invoiceRows && invoiceRows.length > 1) {
      for (let i = 1; i < invoiceRows.length; i++) {
        const row = invoiceRows[i] as unknown[];
        if (toStr(row[6]) !== projectName) continue;
        if (toStr(row[3]) !== 'invoice') continue;
        const serial = toNumber(row[1]);
        if (serial > 0) monthSet.add(serialToMonthLabel(serial));
      }
    }

    const months = Array.from(monthSet).sort(
      (a, b) => monthLabelSortValue(a) - monthLabelSortValue(b)
    );

    if (months.length === 0) {
      // Return empty-but-valid payload rather than an error
      const emptyData: ProjectDetailData = {
        project: projectName,
        availableProjects: KNOWN_PROJECTS,
        months: [],
        cosActual: Object.fromEntries(COS_CATEGORIES.map(c => [c, emptyMonthly([])])),
        cosTotal: emptyMonthly([]),
        summary: {
          activations: emptyMonthly([]),
          revenue: emptyMonthly([]),
          gross: emptyMonthly([]),
          net: emptyMonthly([]),
        },
      };
      return NextResponse.json({ success: true, data: emptyData });
    }

    // -----------------------------------------------------------------------
    // Pass 2: Accumulate COS actuals from Data tab
    // -----------------------------------------------------------------------
    const cosActual: Record<string, MonthlyValues> = Object.fromEntries(
      COS_CATEGORIES.map(c => [c, emptyMonthly(months)])
    );
    const cosTotal = emptyMonthly(months);

    for (let i = 1; i < dataRows.length; i++) {
      const row = dataRows[i] as unknown[];
      if (toStr(row[15]) !== projectName) continue;
      if (toStr(row[13]) !== 'Included') continue;
      if (toStr(row[2]) !== 'Expense') continue;
      const cat = toStr(row[10]);
      if (!cat.startsWith('COS')) continue;

      const serial = toNumber(row[0]);
      if (serial <= 0) continue;
      const month = serialToMonthLabel(serial);

      const amount = toNumber(row[5]);

      // Use known category bucket or catch-all
      const bucket = COS_CATEGORIES.includes(cat) ? cat : COS_CATEGORIES[0];
      accumulate(cosActual[bucket], month, amount);
      accumulate(cosTotal, month, amount);
    }

    // -----------------------------------------------------------------------
    // Pass 3: Revenue + activation count from FT_Invoice tab
    // -----------------------------------------------------------------------
    const revenue = emptyMonthly(months);
    const activations = emptyMonthly(months);

    if (invoiceRows && invoiceRows.length > 1) {
      for (let i = 1; i < invoiceRows.length; i++) {
        const row = invoiceRows[i] as unknown[];
        if (toStr(row[6]) !== projectName) continue;
        if (toStr(row[3]) !== 'invoice') continue;

        const serial = toNumber(row[1]);
        if (serial <= 0) continue;
        const month = serialToMonthLabel(serial);

        const amount = toNumber(row[9]);
        accumulate(revenue, month, amount);
        // Count rows (activations) — increment by 1 not by amount
        accumulate(activations, month, 1);
      }
    }

    // -----------------------------------------------------------------------
    // Pass 4: Compute Gross = Revenue - COS per month
    // -----------------------------------------------------------------------
    const gross = emptyMonthly(months);
    for (const month of months) {
      const val = (revenue.monthly[month] ?? 0) - (cosTotal.monthly[month] ?? 0);
      gross.monthly[month] = val;
      gross.total += val;
    }

    // Net = Gross (no further deductions at this data level)
    const net: MonthlyValues = {
      total: gross.total,
      monthly: { ...gross.monthly },
    };

    const data: ProjectDetailData = {
      project: projectName,
      availableProjects: KNOWN_PROJECTS,
      months,
      cosActual,
      cosTotal,
      summary: { activations, revenue, gross, net },
    };

    logger.info('Project Detail data assembled', {
      projectName,
      months: months.length,
      cosTotal: cosTotal.total,
      revenueTotal: revenue.total,
    });

    return NextResponse.json({ success: true, data });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Project Detail fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

