#### 3. **REACT QUERY HOOK PATTERN** (used in ALL hooks)

```typescript
import { useQuery } from '@tanstack/react-query';

async function fetchData(): Promise<ResponseType> {
  const res = await fetch('/api/analytics/reports/XXX');
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    throw new Error(body.error?.message ?? 'Failed to load data');
  }
  return res.json() as Promise<ResponseType>;
}

export function useDataHook() {
  return useQuery<ResponseType, Error>({
    queryKey: ['analytics', 'report-id'],
